    return h + K.f(v.l ?? 0, K.l(50, y - (v.p ?? 0) * u, 316, y - (v.p ?? 0) * u, 'lf d') + K.t(318, y - (v.p ?? 0) * u - 6, N(v.p ?? 0), 'tf', 'end'));
