  const donde = (x, y) => { if (x < 10 || x > 330 || y < 4 || y > 202) return -1; const a = Math.hypot(x - AX, y - CY) <= R, b = Math.hypot(x - BX, y - CY) <= R; return a && b ? 1 : a ? 0 : b ? 2 : 3; };

