    bolas: [110, (v, K, p) => XM.bolas(K, 34, 34, v.a ?? p.a, 'fa', Math.min(26, 270 / (p.M || 10)), 9) + XM.bolas(K, 34, 78, v.b ?? p.b, 'fg', Math.min(26, 270 / (p.M || 10)), 9)],
