      const ticks = (s.ticks || []).map(v => `<line x1="${px(v)}" y1="${y - 5}" x2="${px(v)}" y2="${y + 5}" style="stroke:var(--mute)" stroke-width="1.2"/>${txt(v, px(v), y + 20, { s: 11, c: 'mute' })}`).join('');
