  if (c.blocks) return c.blocks.map(b => ({ b, name: b.name, ...cuenta(c.units.filter(u => u.block === b.id)) }));
  return [{ name: 'Mundos completos', d: c.units.filter(u => u.lessons.every(hecha)).length, n: c.units.length }];
