  window.zukaListo = () => { const f = document.querySelector('#portal'); if (!f) return; f.dataset.listo = '1'; if (tab === 'portal') { view.innerHTML = ''; portalVe(true); f.focus(); } else f.hidden = true; };
  window.zukaFalla = portalFalla;
